  /**
   * @method
   * @name cryptocom#fetchCurrencies
   * @description fetches all available currencies on an exchange
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-get-currency-networks
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an associative dictionary of currencies
   */
  std::shared_future<ccxt::any>
  fetchCurrencies(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // this endpoint requires authentication
                 if (!isTrue(this->checkRequiredCredentials(false))) {
                   return ccxt::dict{};
                 }
                 ccxt::any skipFetchCurrencies = false;
                 ccxt::any skipFetchCurrenciesparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchCurrencies"),
                         std::string("skipFetchCurrencies"), false);
                 skipFetchCurrencies =
                     ::getValue(skipFetchCurrenciesparamsVariable, 0);
                 params = ::getValue(skipFetchCurrenciesparamsVariable, 1);
                 if (isTrue(skipFetchCurrencies)) {
                   // sub-accounts can't access this endpoint
                   return ccxt::dict{};
                 }
                 ccxt::any response = ccxt::dict{};
                 try {
                   response = awaitValue(
                       this->v1PrivatePostPrivateGetCurrencyNetworks(params));
                 } catch (const std::exception &e) {
                   ccxt::any erString = this->exceptionMessage(e);
                   if (isTrue(isGreaterThanOrEqual(
                           getIndexOf(erString, std::string("SYS_ERROR")),
                           0))) {
                     // sub-accounts can't access this endpoint
                     // {"code":"10001","msg":"SYS_ERROR"}
                     return ccxt::dict{};
                   }
                   throw;
                 }
                 //
                 //    {
                 //        "id": "1747502328559",
                 //        "method": "private/get-currency-networks",
                 //        "code": "0",
                 //        "result": {
                 //            "update_time": "1747502281000",
                 //            "currency_map": {
                 //                "USDT": {
                 //                    "full_name": "Tether USD",
                 //                    "default_network": "ETH",
                 //                    "network_list": [
                 //                        {
                 //                            "network_id": "ETH",
                 //                            "withdrawal_fee": "10.00000000",
                 //                            "withdraw_enabled": true,
                 //                            "min_withdrawal_amount": "20.0",
                 //                            "deposit_enabled": true,
                 //                            "confirmation_required": "32"
                 //                        },
                 //                        {
                 //                            "network_id": "CRONOS",
                 //                            "withdrawal_fee": "0.18000000",
                 //                            "withdraw_enabled": true,
                 //                            "min_withdrawal_amount": "0.35",
                 //                            "deposit_enabled": true,
                 //                            "confirmation_required": "15"
                 //                        },
                 //                        {
                 //                            "network_id": "SOL",
                 //                            "withdrawal_fee": "5.31000000",
                 //                            "withdraw_enabled": true,
                 //                            "min_withdrawal_amount": "10.62",
                 //                            "deposit_enabled": true,
                 //                            "confirmation_required": "1"
                 //                        }
                 //                    ]
                 //                }
                 //            }
                 //        }
                 //    }
                 //
                 ccxt::any resultData = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any currencyMap = this->safeDict(
                     resultData, std::string("currency_map"), ccxt::dict{});
                 ccxt::any enhancedArray = this->addKeyInArrayItems(
                     currencyMap, std::string("_coin_id"));
                 return this->parseCurrencies(enhancedArray);
               })
        .share();
  }

  ccxt::any parseCurrency(ccxt::any currency) override {
    ccxt::any id = this->safeString(currency, std::string("_coin_id"));
    ccxt::any code = this->safeCurrencyCode(id);
    ccxt::any networks = ccxt::dict{};
    ccxt::any chains =
        this->safeList(currency, std::string("network_list"), ccxt::list{});
    for (ccxt::any j = 0; isLessThan(j, getArrayLength(chains));
         postFixIncrement(j)) {
      ccxt::any chain = ::getValue(chains, j);
      ccxt::any networkId = this->safeString(chain, std::string("network_id"));
      ccxt::any network = this->networkIdToCode(networkId, code);
      if (isTrue(!isEqual(network, ccxt::any{}))) {
        ::setValue(
            networks, network,
            ccxt::dict{
                {std::string("info"), chain},
                {std::string("id"), networkId},
                {std::string("network"), network},
                {std::string("active"), ccxt::any{}},
                {std::string("deposit"),
                 this->safeBool(chain, std::string("deposit_enabled"), false)},
                {std::string("withdraw"),
                 this->safeBool(chain, std::string("withdraw_enabled"), false)},
                {std::string("fee"),
                 this->safeNumber(chain, std::string("withdrawal_fee"))},
                {std::string("precision"), ccxt::any{}},
                {std::string("limits"),
                 ccxt::dict{
                     {std::string("withdraw"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(
                               chain, std::string("min_withdrawal_amount"))},
                          {std::string("max"), ccxt::any{}},
                      }},
                 }},
            });
      }
    }
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("info"), currency},
        {std::string("id"), id},
        {std::string("code"), code},
        {std::string("name"),
         this->safeString(currency, std::string("full_name"))},
        {std::string("active"), ccxt::any{}},
        {std::string("deposit"), ccxt::any{}},
        {std::string("withdraw"), ccxt::any{}},
        {std::string("fee"), ccxt::any{}},
        {std::string("precision"), ccxt::any{}},
        {std::string("limits"),
         ccxt::dict{
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("type"), std::string("crypto")},
        {std::string("networks"), networks},
    });
  }

