  /**
   * @method
   * @name cryptocom#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#public-get-candlestick
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms for the ending date filter,
   * default is the current time
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"), std::string("paginate"),
                     false);
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, 300));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("instrument_name"),
                      ::getValue(market, std::string("id"))},
                     {std::string("timeframe"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   if (isTrue(isGreaterThan(limit, 300))) {
                     limit = 300;
                   }
                   ::setValue(request, std::string("count"), limit);
                 }
                 ccxt::any now = this->microseconds();
                 ccxt::any duration = this->parseTimeframe(timeframe);
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"), now);
                 params = this->omit(params, ccxt::list{std::string("until")});
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_ts"),
                              subtract(since, multiply(duration, 1000)));
                   if (isTrue(!isEqual(limit, ccxt::any{}))) {
                     ::setValue(
                         request, std::string("end_ts"),
                         this->sum(since,
                                   multiply(multiply(duration, limit), 1000)));
                   } else {
                     ::setValue(request, std::string("end_ts"), until);
                   }
                 } else {
                   ::setValue(request, std::string("end_ts"), until);
                 }
                 ccxt::any response =
                     awaitValue(this->v1PublicGetPublicGetCandlestick(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "id": -1,
                 //         "method": "public/get-candlestick",
                 //         "code": 0,
                 //         "result": {
                 //             "interval": "1m",
                 //             "data": [
                 //                 {
                 //                     "o": "26949.89",
                 //                     "h": "26957.64",
                 //                     "l": "26948.24",
                 //                     "c": "26950.00",
                 //                     "v": "0.0670",
                 //                     "t": 1687237080000
                 //                 },
                 //             ],
                 //             "instrument_name": "BTC_USD"
                 //         }
                 //     }
                 //
                 ccxt::any result = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any data =
                     this->safeList(result, std::string("data"), ccxt::list{});
                 return this->parseOHLCVs(data, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  /**
   * @method
   * @name cryptocom#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#public-get-book
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the number of order book entries to return, max 50
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("instrument_name"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(isTrue((!isEqual(limit, ccxt::any{}))) &&
                            isTrue((!isEqual(limit, 0))))) {
                   ::setValue(request, std::string("depth"),
                              mathMin(limit, 50)); // max 50
                 }
                 ccxt::any response = awaitValue(this->v1PublicGetPublicGetBook(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "id": -1,
                 //         "method": "public/get-book",
                 //         "code": 0,
                 //         "result": {
                 //             "depth": 3,
                 //             "data": [
                 //                 {
                 //                     "bids": [ [ "30025.00", "0.00004", "1"
                 //                     ], [ "30020.15", "0.02498", "1" ], [
                 //                     "30020.00", "0.00004", "1" ] ], "asks":
                 //                     [ [ "30025.01", "0.04090", "1" ], [
                 //                     "30025.70", "0.01000", "1" ], [
                 //                     "30026.94", "0.02681", "1" ] ], "t":
                 //                     1687491287380
                 //                 }
                 //             ],
                 //             "instrument_name": "BTC_USD"
                 //         }
                 //     }
                 //
                 ccxt::any result = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any data =
                     this->safeList(result, std::string("data"), ccxt::list{});
                 ccxt::any orderBook = this->safeValue(data, 0);
                 ccxt::any timestamp =
                     this->safeInteger(orderBook, std::string("t"));
                 return this->parseOrderBook(orderBook, symbol, timestamp);
               })
        .share();
  }

  ccxt::any parseBalance(ccxt::any response) override {
    ccxt::any responseResult =
        this->safeDict(response, std::string("result"), ccxt::dict{});
    ccxt::any data =
        this->safeList(responseResult, std::string("data"), ccxt::list{});
    ccxt::any positionBalances = this->safeValue(
        ::getValue(data, 0), std::string("position_balances"), ccxt::list{});
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
    };
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(positionBalances));
         postFixIncrement(i)) {
      ccxt::any balance = ::getValue(positionBalances, i);
      ccxt::any currencyId =
          this->safeString(balance, std::string("instrument_name"));
      ccxt::any code = this->safeCurrencyCode(currencyId);
      ccxt::any account = this->account();
      ::setValue(account, std::string("total"),
                 this->safeString(balance, std::string("quantity")));
      ::setValue(account, std::string("used"),
                 this->safeString(balance, std::string("reserved_qty")));
      if (isTrue(!isEqual(code, ccxt::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

