  /**
   * @method
   * @name cryptocom#cancelOrders
   * @description cancel multiple orders
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-cancel-order-list-list
   * @param {string[]} ids order ids
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrders(ccxt::any ids, ccxt::any symbol = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any orderRequests = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(ids));
                      postFixIncrement(i)) {
                   ccxt::any id = ::getValue(ids, i);
                   ccxt::any order = ccxt::dict{
                       {std::string("instrument_name"),
                        ::getValue(market, std::string("id"))},
                       {std::string("order_id"), toString(id)},
                   };
                   arrayPush(orderRequests, order);
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("contingency_type"), std::string("LIST")},
                     {std::string("order_list"), orderRequests},
                 };
                 ccxt::any response =
                     awaitValue(this->v1PrivatePostPrivateCancelOrderList(
                         this->extend(request, params)));
                 ccxt::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseOrders(result, market, ccxt::any{},
                                          ccxt::any{}, params);
               })
        .share();
  }

  /**
   * @method
   * @name cryptocom#cancelOrdersForSymbols
   * @description cancel multiple orders for multiple symbols
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-cancel-order-list-list
   * @param {CancellationRequest[]} orders each order should contain the
   * parameters required by cancelOrder namely id and symbol, example [{"id":
   * "a", "symbol": "BTC/USDT"}, {"id": "b", "symbol": "ETH/USDT"}]
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrdersForSymbols(ccxt::any orders,
                         ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any orderRequests = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   ccxt::any order = ::getValue(orders, i);
                   ccxt::any id = this->safeString(order, std::string("id"));
                   ccxt::any symbol =
                       this->safeString(order, std::string("symbol"));
                   ccxt::any market = this->market(symbol);
                   ccxt::any orderItem = ccxt::dict{
                       {std::string("instrument_name"),
                        ::getValue(market, std::string("id"))},
                       {std::string("order_id"), toString(id)},
                   };
                   arrayPush(orderRequests, orderItem);
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("contingency_type"), std::string("LIST")},
                     {std::string("order_list"), orderRequests},
                 };
                 ccxt::any response =
                     awaitValue(this->v1PrivatePostPrivateCancelOrderList(
                         this->extend(request, params)));
                 ccxt::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseOrders(result, ccxt::any{}, ccxt::any{},
                                          ccxt::any{}, params);
               })
        .share();
  }

