  /**
   * @method
   * @name cryptocom#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-get-trades
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for, maximum
   * date range is one day
   * @param {int} [limit] the maximum number of trade structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms for the ending date filter,
   * default is the current time
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params, 100));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("instrument_name"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_time"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, ccxt::list{std::string("until")});
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("end_time"), until);
                 }
                 ccxt::any response =
                     awaitValue(this->v1PrivatePostPrivateGetTrades(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "id": 1686942003520,
                 //         "method": "private/get-trades",
                 //         "code": 0,
                 //         "result": {
                 //             "data": [
                 //                 {
                 //                     "account_id":
                 //                     "ds075abc-1234-4321-bd6g-ff9007252r63",
                 //                     "event_date": "2023-06-16",
                 //                     "journal_type": "TRADING",
                 //                     "side": "BUY",
                 //                     "instrument_name": "BTC_USD",
                 //                     "fees": "-0.0000000525",
                 //                     "trade_id": "6142909898247428343",
                 //                     "trade_match_id": "4611686018455978480",
                 //                     "create_time": 1686941992887,
                 //                     "traded_price": "26347.16",
                 //                     "traded_quantity": "0.00021",
                 //                     "fee_instrument_name": "BTC",
                 //                     "client_oid":
                 //                     "d1c70a60-810e-4c92-b2a0-72b931cb31e0",
                 //                     "taker_side": "TAKER",
                 //                     "order_id": "6142909895036331486",
                 //                     "create_time_ns": "1686941992887207066"
                 //                 }
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any result = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any trades =
                     this->safeList(result, std::string("data"), ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  virtual ccxt::any parseAddress(ccxt::any addressString) {
    ccxt::any address = ccxt::any{};
    ccxt::any tag = ccxt::any{};
    ccxt::any rawTag = ccxt::any{};
    if (isTrue(isGreaterThan(getIndexOf(addressString, std::string("?")), 0))) {
      ccxt::any addressrawTagVariable = split(addressString, std::string("?"));
      address = ::getValue(addressrawTagVariable, 0);
      rawTag = ::getValue(addressrawTagVariable, 1);
      ccxt::any splitted = split(rawTag, std::string("="));
      tag = ::getValue(splitted, 1);
    } else {
      address = addressString;
    }
    return ccxt::list{address, tag};
  }

  /**
   * @method
   * @name cryptocom#withdraw
   * @description make a withdrawal
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-create-withdrawal
   * @param {string} code unified currency code
   * @param {float} amount the amount to withdraw
   * @param {string} address the address to withdraw to
   * @param {string} tag
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  withdraw(ccxt::any code, ccxt::any amount, ccxt::any address,
           ccxt::any tag = ccxt::any{},
           ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any tagparamsVariable =
                     this->handleWithdrawTagAndParams(tag, params);
                 tag = ::getValue(tagparamsVariable, 0);
                 params = ::getValue(tagparamsVariable, 1);
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = this->safeCurrency(
                     code); // for instance, USDC is not inferred from markets
                            // but it's still available
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("amount"), amount},
                     {std::string("address"), address},
                 };
                 if (isTrue(!isEqual(tag, ccxt::any{}))) {
                   ::setValue(request, std::string("address_tag"), tag);
                 }
                 ccxt::any networkCode = ccxt::any{};
                 ccxt::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 ccxt::any networkId = this->networkCodeToId(networkCode, code);
                 if (isTrue(!isEqual(networkId, ccxt::any{}))) {
                   ::setValue(request, std::string("network_id"), networkId);
                 }
                 ccxt::any response =
                     awaitValue(this->v1PrivatePostPrivateCreateWithdrawal(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "id":-1,
                 //        "method":"private/create-withdrawal",
                 //        "code":0,
                 //        "result": {
                 //            "id": 2220,
                 //            "amount": 1,
                 //            "fee": 0.0004,
                 //            "symbol": "BTC",
                 //            "address": "2NBqqD5GRJ8wHy1PYyCXTe9ke5226FhavBf",
                 //            "client_wid": "my_withdrawal_002",
                 //            "create_time":1607063412000
                 //        }
                 //     }
                 //
                 ccxt::any result =
                     this->safeDict(response, std::string("result"));
                 return this->parseTransaction(result, currency);
               })
        .share();
  }

  /**
   * @method
   * @name cryptocom#fetchDepositAddressesByNetwork
   * @description fetch a dictionary of addresses for a currency, indexed by
   * network
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-get-deposit-address
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [address structures]{@link
   * https://docs.ccxt.com/?id=address-structure} indexed by the network
   */
  std::shared_future<ccxt::any>
  fetchDepositAddressesByNetwork(ccxt::any code,
                                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = this->safeCurrency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 ccxt::any response =
                     awaitValue(this->v1PrivatePostPrivateGetDepositAddress(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "id": 1234555011221,
                 //         "method": "private/get-deposit-address",
                 //         "code": 0,
                 //         "result": {
                 //             "deposit_address_list": [
                 //                 {
                 //                     "currency": "BTC",
                 //                     "create_time": 1686730755000,
                 //                     "id": "3737377",
                 //                     "address":
                 //                     "3N9afggxTSmJ3H4jaMQuWyEiLBzZdAbK6d",
                 //                     "status":"1",
                 //                     "network": "BTC"
                 //                 },
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any addresses = this->safeList(
                     data, std::string("deposit_address_list"), ccxt::list{});
                 ccxt::any addressesLength = getArrayLength(addresses);
                 if (isTrue(isEqual(addressesLength, 0))) {
                   throw ExchangeError(toString(add(
                       this->id, std::string(" fetchDepositAddressesByNetwork()"
                                             " generating address..."))));
                 }
                 ccxt::any result = ccxt::dict{};
                 for (ccxt::any i = 0; isLessThan(i, addressesLength);
                      postFixIncrement(i)) {
                   ccxt::any value = this->safeDict(addresses, i);
                   ccxt::any addressString =
                       this->safeString(value, std::string("address"));
                   ccxt::any currencyId =
                       this->safeString(value, std::string("currency"));
                   ccxt::any responseCode = this->safeCurrencyCode(currencyId);
                   ccxt::any addresstagVariable =
                       this->parseAddress(addressString);
                   ccxt::any address = ::getValue(addresstagVariable, 0);
                   ccxt::any tag = ::getValue(addresstagVariable, 1);
                   this->checkAddress(address);
                   ccxt::any networkId =
                       this->safeString(value, std::string("network"));
                   ccxt::any network =
                       this->networkIdToCode(networkId, responseCode);
                   if (isTrue(!isEqual(network, ccxt::any{}))) {
                     ::setValue(result, network,
                                ccxt::dict{
                                    {std::string("info"), value},
                                    {std::string("currency"), responseCode},
                                    {std::string("network"), network},
                                    {std::string("address"), address},
                                    {std::string("tag"), tag},
                                });
                   }
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name cryptocom#fetchDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-get-deposit-address
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<ccxt::any>
  fetchDepositAddress(ccxt::any code,
                      ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any network =
                     this->safeStringUpper(params, std::string("network"));
                 params =
                     this->omit(params, ccxt::list{std::string("network")});
                 ccxt::any depositAddressesRaw = awaitValue(
                     this->fetchDepositAddressesByNetwork(code, params));
                 ccxt::any depositAddresses = depositAddressesRaw;
                 if (isTrue(inOp(depositAddresses, network))) {
                   return ::getValue(depositAddresses, network);
                 }
                 ccxt::any keys = getObjectKeys(depositAddresses);
                 return ::getValue(depositAddresses, ::getValue(keys, 0));
               })
        .share();
  }

  /**
   * @method
   * @name cryptocom#fetchDeposits
   * @description fetch all deposits made to an account
   * @see
   * https://exchange-docs.crypto.com/exchange/v1/rest-ws/index.html#private-get-deposit-history
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of deposits structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms for the ending date filter,
   * default is the current time
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchDeposits(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = ccxt::any{};
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(code, ccxt::any{}))) {
                   currency = this->safeCurrency(code);
                   ::setValue(request, std::string("currency"),
                              ::getValue(currency, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   // 90 days date range
                   ::setValue(request, std::string("start_ts"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("page_size"), limit);
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, ccxt::list{std::string("until")});
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("end_ts"), until);
                 }
                 ccxt::any response =
                     awaitValue(this->v1PrivatePostPrivateGetDepositHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "id": 1688701375714,
                 //         "method": "private/get-deposit-history",
                 //         "code": 0,
                 //         "result": {
                 //             "deposit_list": [
                 //                 {
                 //                     "currency": "BTC",
                 //                     "fee": 0,
                 //                     "create_time": 1688023659000,
                 //                     "id": "6201135",
                 //                     "update_time": 1688178509000,
                 //                     "amount": 0.00114571,
                 //                     "address":
                 //                     "1234fggxTSmJ3H4jaMQuWyEiLBzZdAbK6d",
                 //                     "status": "1",
                 //                     "txid":
                 //                     "f0ae4202b76eb999c301eccdde44dc639bee42d1fdd5974105286ca3393f6065/2"
                 //                 },
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(
                     response, std::string("result"), ccxt::dict{});
                 ccxt::any depositList = this->safeList(
                     data, std::string("deposit_list"), ccxt::list{});
                 return this->parseTransactions(depositList, currency, since,
                                                limit);
               })
        .share();
  }

